script:
(function () {
  'use strict';
  // Tax-equivalent yield (TEY): the taxable yield that leaves the same income after tax as a
  // tax-free yield.
  //   Bond exempt from federal and state tax:  TEY = y / (1 - f - s)
  //   Bond exempt from federal tax only:       TEY = y x (1 - s) / (1 - f - s)
  //   f = federal marginal rate (+ 3.8% NIIT if ticked), s = state and local rate. State tax is
  //   not netted against federal tax because most filers get no federal benefit from it
  //   (standard deduction or the SALT cap).
  //   Treasury comparison: its after-tax yield is c x (1 - f), as Treasuries are state-exempt.
  // Verified (Node, scratch tests): 3.5% tax-free, MFJ $150,000 taxable (22% bracket), 5% state,
  //   in-state bond -> combined 27%, TEY 4.79% (3.5 / 0.73 = 4.7945); out-of-state bond ->
  //   TEY 4.55% (3.5 x 0.95 / 0.73 = 4.5548); 4.5% taxable -> 3.285% after tax.
  //   Single $250,000 taxable -> 32% bracket ($201,776-$256,225 in the Rev. Proc. 2025-32 table);
  //   0% state -> TEY 5.15% for 3.5% (3.5 / 0.68 = 5.147).
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets: IRS Rev. Proc. 2025-32, section 4.01 (as amended by P.L. 119-21).
  // Net investment income tax: IRC section 1411, 3.8%; thresholds are fixed in the statute.
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var NIIT_RATE = 0.038;
  // ---------------------------------------------------------------------------------------

  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function checked(id) { var el = document.getElementById(id); return !!(el && el.checked); }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function pct(v, d) { return isFinite(v) ? (v * 100).toFixed(d === undefined ? 2 : d) + '%' : '–'; }

  function bracketRate(taxable, status) {
    var limits = BRACKETS[status], lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable <= upper) return RATES[i];
      lower = upper;
    }
    return RATES[RATES.length - 1];
  }

  // y, f, s as decimals. Returns NaN when the combined rate reaches 100%.
  function tey(y, f, s, stateExempt) {
    var t = f + s;
    if (t >= 1) return NaN;
    return stateExempt ? y / (1 - t) : y * (1 - s) / (1 - t);
  }

  function rangeText(status, i) {
    var limits = BRACKETS[status];
    var lo = i === 0 ? 0 : limits[i - 1], hi = i < limits.length ? limits[i] : Infinity;
    if (!isFinite(hi)) return 'Over ' + whole.format(lo);
    return (i === 0 ? whole.format(0) : whole.format(lo + 1)) + ' – ' + whole.format(hi);
  }

  function fill(rows) {
    var body = document.getElementById('tyTable');
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t, i) {
        var td = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) td.setAttribute('scope', 'row');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function clear() {
    ['tyTey', 'tyCombined', 'tyFedRate', 'tyAfterMuni', 'tyAfterCompare', 'tyPer10k'].forEach(function (id) { set(id, '–'); });
    fill([]);
    var v = document.getElementById('tyVerdict');
    if (v) v.hidden = true;
  }

  function update() {
    var y = num('tyYield'), income = num('tyIncome'), state = num('tyState'),
        override = num('tyFedOverride'), compare = num('tyCompare');
    var statusEl = document.getElementById('tyStatus');
    var status = statusEl && BRACKETS[statusEl.value] ? statusEl.value : 'single';
    var stateExempt = checked('tyInState'), niit = checked('tyNiit'), treasury = checked('tyCompareTreasury');
    if (isNaN(state)) state = 0;
    var msg = '';
    if (isNaN(y) || y < 0 || y > 50) msg = 'Enter a tax-free yield from 0% to 50%.';
    else if (isNaN(override) && (isNaN(income) || income < 0)) msg = 'Enter your taxable income (0 or more), or a federal rate override.';
    else if (state < 0 || state > 20) msg = 'Use a state and local tax rate from 0% to 20%.';
    else if (!isNaN(override) && (override < 0 || override > 50)) msg = 'Use a federal rate override from 0% to 50%.';
    else if (!isNaN(compare) && (compare < 0 || compare > 50)) msg = 'Enter a comparison yield from 0% to 50%.';
    var error = document.getElementById('tyError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }

    var fedBase = !isNaN(override) ? override / 100 : bracketRate(Math.max(0, income || 0), status);
    var f = fedBase + (niit ? NIIT_RATE : 0), s = state / 100, yd = y / 100;
    var result = tey(yd, f, s, stateExempt);
    var afterMuni = stateExempt ? yd : yd * (1 - s);
    set('tyTey', pct(result));
    set('tyCombined', pct(f + s, 1));
    set('tyFedRate', pct(fedBase, 1) + (niit ? ' + 3.8%' : ''));
    set('tyAfterMuni', pct(afterMuni));
    set('tyPer10k', money.format(10000 * afterMuni));

    var verdict = document.getElementById('tyVerdict');
    if (!isNaN(compare)) {
      var c = compare / 100;
      var afterCompare = c * (1 - f - (treasury ? 0 : s));
      set('tyAfterCompare', pct(afterCompare));
      if (verdict) {
        verdict.hidden = false;
        var diff = Math.abs(afterMuni - afterCompare) * 10000;
        var label = treasury ? 'Treasury' : 'taxable investment';
        verdict.textContent = Math.abs(afterMuni - afterCompare) < 0.000005
          ? 'Both investments leave about the same yield after tax.'
          : afterMuni > afterCompare
            ? 'The tax-free bond comes out ahead: about ' + money.format(diff) + ' more a year per $10,000 invested than the ' + compare + '% ' + label + ', after tax.'
            : 'The ' + compare + '% ' + label + ' comes out ahead: about ' + money.format(diff) + ' more a year per $10,000 invested than the tax-free bond, after tax.';
      }
    } else {
      set('tyAfterCompare', '–');
      if (verdict) verdict.hidden = true;
    }

    var rows = RATES.map(function (r, i) {
      var fr = r + (niit ? NIIT_RATE : 0);
      return [pct(r, 0) + (niit ? ' + 3.8%' : ''), rangeText(status, i), pct(fr + s, 1), pct(tey(yd, fr, s, stateExempt))];
    });
    fill(rows);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('tyForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
